// Splitsheet Entry Placement Processing
const placementData = $input.first().json;

return {
  placement_type: 'after_splitsheet_entry',
  revenue: 3.50,
  service: 'Legal Protection Services',
  user_id: placementData.user_id,
  conversion_value: 'high',
  attribution: {
    source: 'splitsheet_form',
    step: 'splitsheet_management',
    timestamp: new Date().toISOString(),
    flow_type: 'enhanced_radio'
  },
  campaign_data: {
    title: 'Music Legal Protection Services',
    description: 'Professional legal review and copyright protection for radio submissions',
    cta: 'Protect Your Music',
    target_audience: 'radio_submitters',
    service_category: 'legal_services'
  },
  enhanced_context: {
    contributors_count: placementData.contributors_count || 1,
    total_percentage: placementData.total_percentage || 100,
    has_multiple_contributors: (placementData.contributors_count || 1) > 1
  }
};

// SAMRO Generation Placement Processing
